import{_ as e,o as t,c as l,a0 as s}from"./chunks/framework.MyDJm6cd.js";const f=JSON.parse('{"title":"fleetd vault 设计：机器间密钥/账号/额度统一管理","description":"","frontmatter":{},"headers":[],"relativePath":"vault-design.md","filePath":"vault-design.md"}'),n={name:"vault-design.md"};function i(o,a,d,p,r,c){return t(),l("div",null,[...a[0]||(a[0]=[s(`<h1 id="fleetd-vault-设计-机器间密钥-账号-额度统一管理" tabindex="-1">fleetd vault 设计：机器间密钥/账号/额度统一管理 <a class="header-anchor" href="#fleetd-vault-设计-机器间密钥-账号-额度统一管理" aria-label="Permalink to &quot;fleetd vault 设计：机器间密钥/账号/额度统一管理&quot;">​</a></h1><p>状态：设计定稿（2026-11-27，用户确认范围），待实现。 前置事实：<strong>persona vault 已存在且在役</strong>（gateway-fleet 的 24 个 api_key 权威源，unix socket + pconn token，litellm/hermes/bifrost 全在消费）。 fleetd <strong>不自建密钥库</strong>，做 persona 的 fleet 分发适配层。</p><h2 id="范围-用户令" tabindex="-1">范围（用户令） <a class="header-anchor" href="#范围-用户令" aria-label="Permalink to &quot;范围（用户令）&quot;">​</a></h2><ol><li>机器间密钥统一管理 + 加密传输分发</li><li>订阅账号管理 + 额度查询</li><li>litellm / gateway-fleet 类网关工具纳管</li><li>gateway-fleet 纳入 fleet 管理</li></ol><h2 id="三层架构" tabindex="-1">三层架构 <a class="header-anchor" href="#三层架构" aria-label="Permalink to &quot;三层架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 权威源  persona vault（已存在）</span></span>
<span class="line"><span>   ├─ 24 api_key items（zai/kimi/sensenova/xiaomi/qiniu/ark/bifrost/glm…）</span></span>
<span class="line"><span>   ├─ unix socket + pconn token（scoped read-only）</span></span>
<span class="line"><span>   └─ 新增条目类型：订阅账号（provider/plan/expiry/额度查询端点）</span></span>
<span class="line"><span>2. fleetd 分发适配层（新实现）</span></span>
<span class="line"><span>   ├─ fleetd tools config sync：persona 读 → 公钥封装 → 分发</span></span>
<span class="line"><span>   ├─ ship 端落盘 ~/.fleetd/secrets/&lt;name&gt;（0600）</span></span>
<span class="line"><span>   ├─ 通道复用 relay F2 心跳（出站拉取，公网零明文）</span></span>
<span class="line"><span>   └─ agent spawn 注入环境变量（FLEETD_SECRET_*）</span></span>
<span class="line"><span>3. 消费面（已有，不动）</span></span>
<span class="line"><span>   ├─ gateway-fleet fleet_apply 继续管 litellm env.systemd</span></span>
<span class="line"><span>   └─ hermes .env / bifrost / magpie 只读校验链不变</span></span></code></pre></div><h2 id="分工裁决" tabindex="-1">分工裁决 <a class="header-anchor" href="#分工裁决" aria-label="Permalink to &quot;分工裁决&quot;">​</a></h2><table tabindex="0"><thead><tr><th>面</th><th>归属</th><th>理由</th></tr></thead><tbody><tr><td>密钥权威存储</td><td>persona vault</td><td>已在役、有审计、有自动锁策略</td></tr><tr><td>litellm 配置渲染</td><td>gateway-fleet fleet_apply</td><td>已成熟，secret refs 机制完备</td></tr><tr><td>机器间分发</td><td>fleetd（新）</td><td>persona 是单机 unix socket，无跨机面</td></tr><tr><td>额度查询</td><td>fleetd（新）</td><td>聚合各 provider 用量端点 → fleet overview 加列</td></tr><tr><td>agent 生命周期</td><td>fleetd tools 面（同日落地）</td><td>install/inventory/config sync</td></tr></tbody></table><h2 id="实现顺序" tabindex="-1">实现顺序 <a class="header-anchor" href="#实现顺序" aria-label="Permalink to &quot;实现顺序&quot;">​</a></h2><ol><li>F2 心跳通道（ship 出站到 flagship）——vault 分发的载体</li><li>vault 分发：<code>fleetd tools config sync</code>（flagship 拉 persona → 封装下发）</li><li>额度查询：<code>fleetd quota</code>（persona 条目里的 provider 用量端点聚合）</li><li>gateway-fleet 纳管：<code>fleetd status</code> 加 litellm/gateway 服务健康行</li></ol><h2 id="安全边界-用户硬要求-数据外发默认关" tabindex="-1">安全边界（用户硬要求：数据外发默认关） <a class="header-anchor" href="#安全边界-用户硬要求-数据外发默认关" aria-label="Permalink to &quot;安全边界（用户硬要求：数据外发默认关）&quot;">​</a></h2><ul><li>分发默认关：显式 <code>fleetd tools config sync --scope &lt;ship&gt;</code> 才下发</li><li>payload 端到端加密（ship 公钥封装），中继/公网零明文</li><li>flagship 不落任何明文密钥到磁盘（persona 是唯一权威源）</li><li>审计：flagship 记录谁在何时拉了哪个条目</li></ul>`,12)])])}const u=e(n,[["render",i]]);export{f as __pageData,u as default};
